/** Copies text through the async Clipboard API, falling back to execCommand on insecure origins. */
export async function copyTextToClipboard(text: string): Promise<void> {
    // Remote-control pages are served over plain HTTP, so navigator.clipboard is undefined there.
    if (navigator.clipboard) {
        try {
            await navigator.clipboard.writeText(text)
            return
        } catch {
            // Fall through to the legacy path; it still works inside a user-gesture handler.
        }
    }

    const textarea = document.createElement('textarea')
    textarea.value = text
    document.body.appendChild(textarea)
    try {
        textarea.select()
        if (!document.execCommand('copy')) throw new Error('Clipboard copy was refused by the browser')
    } finally {
        textarea.remove()
    }
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { copyTextToClipboard } from './clipboard_text'

function stubClipboard(clipboard: unknown) {
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: clipboard, writable: true })
}

describe('copyTextToClipboard', () => {
    afterEach(() => {
        stubClipboard(undefined)
        vi.restoreAllMocks()
        document.body.innerHTML = ''
    })

    it('writes through the async clipboard API in a secure context', async () => {
        const writeText = vi.fn().mockResolvedValue(undefined)
        stubClipboard({ writeText })
        const execCommand = vi.fn().mockReturnValue(true)
        document.execCommand = execCommand

        await copyTextToClipboard('design/F_116.md')

        expect(writeText).toHaveBeenCalledWith('design/F_116.md')
        expect(execCommand).not.toHaveBeenCalled()
        expect(document.querySelector('textarea')).toBeNull()
    })

    it('falls back to execCommand when navigator.clipboard is missing', async () => {
        stubClipboard(undefined)
        let copiedSelection: string | undefined
        document.execCommand = vi.fn(() => {
            copiedSelection = document.querySelector('textarea')?.value
            return true
        })

        await copyTextToClipboard('design/F_116.md')

        expect(copiedSelection).toBe('design/F_116.md')
        expect(document.querySelector('textarea')).toBeNull()
    })

    it('falls back to execCommand when the clipboard write rejects', async () => {
        const writeText = vi.fn().mockRejectedValue(new Error('Clipboard denied'))
        stubClipboard({ writeText })
        const execCommand = vi.fn().mockReturnValue(true)
        document.execCommand = execCommand

        await copyTextToClipboard('C:\\repo\\design\\F_116.md')

        expect(writeText).toHaveBeenCalledTimes(1)
        expect(execCommand).toHaveBeenCalledWith('copy')
        expect(document.querySelector('textarea')).toBeNull()
    })

    it('rejects and cleans up when execCommand refuses the copy', async () => {
        stubClipboard(undefined)
        document.execCommand = vi.fn().mockReturnValue(false)

        await expect(copyTextToClipboard('design/F_116.md')).rejects.toThrow(/refused/u)
        expect(document.querySelector('textarea')).toBeNull()
    })

    it('removes the textarea when execCommand throws', async () => {
        stubClipboard(undefined)
        document.execCommand = vi.fn(() => {
            throw new Error('execCommand unavailable')
        })

        await expect(copyTextToClipboard('design/F_116.md')).rejects.toThrow('execCommand unavailable')
        expect(document.querySelector('textarea')).toBeNull()
    })
})

import { MenuItem } from '@mui/material'
import { copyTextToClipboard } from '../../services/clipboard_text'
import { dialogService } from '../../services/dialog_service'

interface CardPathMenuItemsProps {
    cardPath: string
    onSelected: () => void
    rootPath?: string
}

function absoluteCardPath(rootPath: string, cardPath: string) {
    const separator = rootPath.includes('\\') ? '\\' : '/'
    const normalizedRootPath = rootPath.replace(/[\\/]+$/gu, '')
    const normalizedCardPath = cardPath.replace(/[\\/]/gu, separator).replace(/^[\\/]+/gu, '')

    return `${normalizedRootPath}${separator}${normalizedCardPath}`
}

async function copyCardPath(path: string, onSelected: () => void) {
    onSelected()
    try {
        await copyTextToClipboard(path)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Path could not be copied to clipboard' })
    }
}

/** Shared path-copy commands for menus representing parsed cards. */
export function CardPathMenuItems(props: CardPathMenuItemsProps) {
    const { cardPath, onSelected, rootPath } = props

    const copyAbsolutePath = () => {
        if (!rootPath) throw new Error('Cannot copy absolute card path without project root path')
        void copyCardPath(absoluteCardPath(rootPath, cardPath), onSelected)
    }

    const copyRelativePath = () => {
        void copyCardPath(cardPath, onSelected)
    }

    return (
        <>
            {rootPath ? <MenuItem onClick={copyAbsolutePath}>Copy path</MenuItem> : null}
            <MenuItem onClick={copyRelativePath}>Copy relative path</MenuItem>
        </>
    )
}

import { Box, Button, Link, Popover, Stack, Typography } from '@mui/material'
import QRCode from 'qrcode'
import { useEffect, useMemo, useState } from 'react'
import type { RemoteControlStatus } from '../../data/electron_remote_control_bridge'
import { connectUrlFromEndpoint } from '../../data/remote_connect_string'
import { copyTextToClipboard } from '../../services/clipboard_text'

interface RemoteControlConnectionInfoProps {
    anchorEl: HTMLElement | null
    onClose: () => void
    open: boolean
    status: RemoteControlStatus
}

interface ConnectTarget {
    connectUrl: string
    endpoint: string
    label: string
}

/**
 * Connect targets to share, IP first: `.local` mDNS resolves unreliably on Android, so a raw LAN IP is
 * the dependable default.
 */
function connectTargets(status: RemoteControlStatus): ConnectTarget[] {
    const targets: ConnectTarget[] = []
    for (const ip of status.ipEndpoints ?? []) {
        const connectUrl = connectUrlFromEndpoint(ip)
        if (connectUrl) targets.push({ connectUrl, endpoint: ip, label: 'IP address' })
    }
    if (status.hostnameEndpoint) {
        const connectUrl = connectUrlFromEndpoint(status.hostnameEndpoint)
        if (connectUrl) targets.push({ connectUrl, endpoint: status.hostnameEndpoint, label: 'Hostname' })
    }

    return targets
}

/** Popover shown from the Serve button: hostname/IP connect links, a copy button and a QR of the selected link. */
export function RemoteControlConnectionInfo(props: RemoteControlConnectionInfoProps) {
    const { anchorEl, onClose, open, status } = props
    const targets = useMemo(() => connectTargets(status), [status])
    const [selectedUrl, setSelectedUrl] = useState<string | null>(null)
    const [qrCode, setQrCode] = useState<{ connectUrl: string, dataUrl: string } | null>(null)
    const [copiedUrl, setCopiedUrl] = useState<string | null>(null)

    // Default the QR/copy target to the first (IP) entry; re-pin if the endpoint set changes.
    const activeUrl = targets.some((target) => target.connectUrl === selectedUrl)
        ? selectedUrl
        : (targets[0]?.connectUrl ?? null)
    const qrDataUrl = qrCode?.connectUrl === activeUrl ? qrCode.dataUrl : null
    const copied = copiedUrl === activeUrl

    useEffect(() => {
        if (!activeUrl) return undefined

        let active = true
        void QRCode.toDataURL(activeUrl, { margin: 1, width: 176 }).then(
            (url) => {
                if (active) setQrCode({ connectUrl: activeUrl, dataUrl: url })
            },
            () => {
                if (active) setQrCode(null)
            },
        )

        return () => {
            active = false
        }
    }, [activeUrl])

    const handleCopy = async () => {
        if (!activeUrl) return
        try {
            await copyTextToClipboard(activeUrl)
        } catch {
            // The connect-URL button has always ignored copy failures; keep it dialog-free.
        }
        setCopiedUrl(activeUrl)
    }

    const handleCopyClick = () => void handleCopy()

    return (
        <Popover
            anchorEl={anchorEl}
            anchorOrigin={{ horizontal: 'left', vertical: 'bottom' }}
            onClose={onClose}
            open={open}
        >
            <Stack spacing={1.5} sx={{ maxWidth: 280, p: 2 }}>
                {targets.length > 0 ? (
                    <Box>
                        <Typography variant="overline">Open on your phone</Typography>
                        <Typography color="text.secondary" variant="caption">
                            IP is most reliable; hostname (.local) may not resolve on Android.
                        </Typography>
                        <Stack spacing={0.5} sx={{ mt: 0.5 }}>
                            {targets.map((target) => (
                                <Link
                                    key={target.connectUrl}
                                    component="button"
                                    onClick={() => setSelectedUrl(target.connectUrl)}
                                    sx={{
                                        fontWeight: target.connectUrl === activeUrl ? 600 : 400,
                                        textAlign: 'left',
                                        wordBreak: 'break-all',
                                    }}
                                    type="button"
                                    variant="body2"
                                >
                                    {target.connectUrl}
                                </Link>
                            ))}
                        </Stack>
                    </Box>
                ) : (
                    <Typography variant="body2">â€”</Typography>
                )}
                {qrDataUrl ? (
                    <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                        <img alt="Remote-control connect QR code" src={qrDataUrl} style={{ maxWidth: '100%' }} />
                    </Box>
                ) : null}
                <Button disabled={!activeUrl} onClick={handleCopyClick} size="small" variant="outlined">
                    {copied ? 'Copied' : 'Copy connect link'}
                </Button>
            </Stack>
        </Popover>
    )
}

import ContentCopyOutlined from '@mui/icons-material/ContentCopyOutlined'
